// === НАСТРОЙКИ ===
const OLLAMA_URL = 'http://172.17.0.1:11434/api/chat';
const MODEL = 'qwen2.5:7b';

// === УСИЛЕННАЯ ОЧИСТКА (удаляет ВСЕ артефакты) ===
const cleanText = (text) => {
  if (!text) return '';

  let cleaned = text;

  // 1. УДАЛЯЕМ СЛУЖЕБНЫЕ ТОКЕНЫ МОДЕЛЕЙ (критично!)
  cleaned = cleaned
    .replace(/<\|im_start\|>/g, '')           // Llama/Ollama start
    .replace(/<\|im_end\|>/g, '')             // Llama/Ollama end
    .replace(/<\|endofprompt\|>/g, '')        // Llama end of prompt
    .replace(/<s>/g, '')                       // BOS token
    .replace(/<\/s>/g, '')                     // EOS token
    .replace(/<\|assistant\|>/g, '')          // Assistant marker
    .replace(/<\|user\|>/g, '')               // User marker
    .replace(/<\|system\|>/g, '')             // System marker
    .replace(/^user\s+/im, '')                // "user " в начале строки
    .replace(/^assistant\s+/im, '')           // "assistant " в начале
    .replace(/^system\s+/im, '')              // "system " в начале
    .replace(/<im_start>/g, '')               // Альтернативный формат
    .replace(/<im_end>/g, '');                // Альтернативный формат

  // 2. УДАЛЯЕМ ВСЕ ИЕРОГЛИФЫ (любые, даже одиночные)
  cleaned = cleaned.replace(/[\u4e00-\u9fff\u3400-\u4dbf\u3000-\u303f]+/g, '');

  // 3. УДАЛЯЕМ markdown и мусор
  cleaned = cleaned
    .replace(/#{1,6}\s+/g, '')                    // Заголовки #
    .replace(/\*\*/g, '')                          // Жирный **
    .replace(/\*/g, '')                            // Курсив *
    .replace(/`{3,}/g, '')                        // Блоки кода ```
    .replace(/`/g, '')                            // Инлайн код `
    .replace(/\[(\d+)\]/g, '')                    // Ссылки [1], [2]
    .replace(/\[(.*?)\]\(.*?\)/g, '$1')          // Ссылки [text](url)
    .replace(/\(\d+\s+(?:слов|words)\)/gi, '')   // (1000 слов)
    .replace(/####?\s+\d+\.\s+/gi, '')           // #### 1.
    .replace(/^[>\-]\s+/gm, '')                   // Цитаты и списки >, -
    .replace(/^\d+\.\s+/gm, '');                  // Нумерованные списки 1.

  // 4. ЧИСТИМ пробелы и переносы
  cleaned = cleaned
    .replace(/\n{4,}/g, '\n\n')                   // Множественные переносы
    .replace(/[ ]{3,}/g, ' ')                     // Множественные пробелы
    .replace(/\s+\n/g, '\n')                      // Пробелы перед переносом
    .replace(/\n\s+/g, '\n')                      // Пробелы после переноса
    .trim();

  // 5. ПРОВЕРЯЕМ НА "БИТЫЙ" КОНЕЦ (обрыв предложения)
  const sentences = cleaned.split(/[.!?]+/).filter(s => s.trim().length > 0);
  const lastSentence = sentences.length > 0 ? sentences[sentences.length - 1].trim() : '';

  const hasBrokenEnd = 
    lastSentence.length > 3 &&                    // Если последний обрывок > 3 слов
    lastSentence.length < 30 &&                   // И короткий (< 30 символов)
    !/[.!?]$/.test(cleaned.trim()) &&            // И не заканчивается на точку
    !/^(на|в|и|но|а|что|как|это|так|же|для|по|от|с|к|у|из|за|под|над|при|без|через|между)\s/i.test(lastSentence); // И не начинается с предлога/союза

  if (hasBrokenEnd) {
    console.log(`    • ⚠️ Текст оборван на конце (последние слова: "${lastSentence.slice(0, 40)}..."), помечаю для дописывания`);
    // Добавляем многоточие как маркер обрыва
    cleaned = cleaned.replace(/([^.!?])\s*$/, '$1...');
  }

  // 6. ПРОВЕРЯЕМ НА ОСТАТОЧНЫЕ АРТЕФАКТЫ
  const hasArtifacts = /<\|im_|<im_|^user\s|^assistant\s|^system\s/i.test(cleaned);
  if (hasArtifacts) {
    console.log(`    • ⚠️ Обнаружены остаточные служебные токены`);
  }

  return cleaned;
};

