let totalArtifactsFound = 0;

for (const [key, raw] of Object.entries(sections)) {
  console.log(`\n[✓] Обрабатываю: ${sectionNames[key]}`);

  // 1. Базовая очистка
  let text = cleanText(raw);

  // 2. Проверка на артефакты после очистки
  const hasArtifacts = /<\|im_|<im_|^user\s|^assistant\s|^system\s|[\u4e00-\u9fff]{2,}/i.test(text);
  if (hasArtifacts) {
    totalArtifactsFound++;
    console.log(`    • ⚠️ Найдены артефакты после очистки`);
  }

  // 3. Проверка объема
  const words = countWords(text);
  const target = targets[key];
  const percent = Math.round((words / target) * 100);

  console.log(`    • Слова: ${words} / ${target} (${percent}%)`);
  report.stats[key] = { words, target, percent };

  // 4. Если мало слов ИЛИ есть артефакты — дописываем/перегенерируем
  const needsExpansion = words < target * 0.8;
  const needsRegen = hasArtifacts && words < target * 0.9;

  if (needsExpansion || needsRegen) {
    if (needsRegen) {
      console.log(`    • ⚠️ Критические артефакты + мало слов, запускаю перегенерацию...`);
    } else {
      console.log(`    • ⚠️ Мало слов, запускаю дописывание...`);
    }

    const needed = Math.round(target - words);
    const prompt = needsRegen 
      ? `ПЕРЕПИШИ раздел "${sectionNames[key]}" по теме "${topic}".

      ТЕКУЩИЙ ТЕКСТ (содержит ошибки/артефакты, замени его полностью):
      ${text.substring(0, 500)}...

      ТРЕБОВАНИЯ:
      1. Объем: МИНИМУМ ${target} слов
      2. Пиши ТОЛЬКО НА РУССКОМ (кроме терминов: Docker, API, JSON и т.п.)
      3. СПЛОШНОЙ академический текст, без списков и заголовков
      4. Раскрой тему глубоко: определения, история, классификации, примеры
      5. НЕ используй служебные токены и markdown

      Верни ПОЛНЫЙ текст раздела.`
      : `ДОПОЛНИ текст раздела "${sectionNames[key]}" по теме "${topic}".

      ТЕКУЩИЙ ТЕКСТ (не повторяй, а РАСШИРИ):
      ${text.substring(0, 800)}...

      ДОБАВЬ (минимум ${needed} слов):
      - Дополнительные примеры, детали, сравнения
      - Исторический контекст или технические нюансы
      - Практические выводы

      ТРЕБОВАНИЯ:
      1. Пиши ТОЛЬКО НА РУССКОМ (кроме терминов: Docker, API, JSON и т.п.)
      2. СПЛОШНОЙ текст, без списков и заголовков
      3. Логически вписывай дополнения в существующий текст

      Верни ТОЛЬКО дополнение, без пояснений.`;

    try {
      const res = await fetch(OLLAMA_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: MODEL,
          messages: [{ role: 'user', content: prompt }],
          stream: false,
          options: { 
            num_predict: needsRegen ? 12000 : 8000,
            temperature: 0.65,
            top_p: 0.9,
            repeat_penalty: 1.15
          }
        })
      });

      const data = await res.json();
      const addition = cleanText(data.message?.content || '');

      if (addition && addition.length > 100) {
        if (needsRegen) {
          text = addition; // Полная замена
          console.log(`    • ✅ Перегенерировано: ${countWords(text)} слов`);
          report.actions.push(`${sectionNames[key]}: перегенерировано (${countWords(text)} слов)`);
        } else {
          text = text + '\n\n' + addition; // Дополнение
          const newWords = countWords(text);
          console.log(`    • ✅ Дописано: +${newWords - words} слов (всего: ${newWords})`);
          report.actions.push(`${sectionNames[key]}: +${newWords - words} слов`);
        }
      } else {
        console.log(`    • ⚠️ Предупреждение: пустой ответ от модели`);
      }
    } catch (e) {
      console.error(`    • ❌ Ошибка: ${e.message}`);
      report.actions.push(`${sectionNames[key]}: ошибка обработки`);
    }
  }

  // 5. Сохраняем результат
  processed[key] = text;
}

