  if (!text) return '';
  return text
    .replace(/#{1,6}\s+/g, '')           // Заголовки #
    .replace(/\*\*/g, '')                 // Жирный **
    .replace(/\(\d+\s+слов\)/gi, '')     // (1000 слов)
    .replace(/####?\s+/g, '')            // #### 
    .replace(/\n{4,}/g, '\n\n')
    .trim();
};

